  "brief": {
    "title": "Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)",
    "one_liner": "A comprehensive trend analysis of intentional homicide rates across countries, sexes, and age groups over three decades, drawing on UNODC data.",
    "goal": "Equip policy analysts and public safety stakeholders with a clear understanding of how homicide rates have evolved globally, which regions and demographics face the highest risk, and where notable improvements or deteriorations have occurred, to inform evidence-based policy recommendations."
  },
  "required_sections": [
    {
      "section_id": "global-overview",
      "title": "Global Homicide Rate Overview",
      "objective": "Present the overall global trend in homicide rates from 1990 to 2023, including the number of countries reporting, the global median and mean rates over time, and a high-level summary of whether the world is becoming safer or more dangerous."
    },
    {
      "section_id": "regional-comparison",
      "title": "Regional & Country-Level Comparison",
      "objective": "Identify the countries and regions with the highest and lowest homicide rates, highlight the top 10 and bottom 10 countries by most recent available year, and discuss geographic patterns."
    },
    {
      "section_id": "sex-disparity",
      "title": "Gender Disparity in Homicide Victimization",
      "objective": "Analyze the difference in homicide rates between males and females globally and across selected countries, quantifying the male-to-female ratio and how it has changed over time."
    },
    {
      "section_id": "age-group-analysis",
      "title": "Age Group Analysis",
      "objective": "Examine which age groups face the highest homicide risk, identify patterns across countries, and assess whether youth or elderly populations are disproportionately affected."
    },
    {
      "section_id": "notable-trends",
      "title": "Notable Country-Level Trends & Outliers",
      "objective": "Highlight countries with the most dramatic increases or decreases in homicide rates over the observation period, discuss potential contextual factors, and flag statistical outliers."
    },
    {
      "section_id": "data-limitations-recommendations",
      "title": "Data Limitations & Policy Recommendations",
      "objective": "Discuss the unbalanced panel nature of the dataset, reporting gaps, and caveats (e.g., UK data covering only England and Wales). Provide actionable policy recommendations based on the findings."
    }
  ],
  "kpis": [
    {
      "name": "Global Median Homicide Rate",
      "description": "The median homicide rate (per 100,000 population) across all countries for the most recent available year, providing a robust central tendency measure."
    },
    {
      "name": "Male-to-Female Homicide Rate Ratio",
      "description": "The ratio of male homicide rate to female homicide rate globally, indicating the degree of gender disparity in victimization."
    },
    {
      "name": "Highest National Homicide Rate",
      "description": "The peak homicide rate observed among all countries in the most recent year with data, identifying the most affected nation."
    },
    {
      "name": "Decade-over-Decade Change",
      "description": "The percentage change in the global average homicide rate between successive decades (e.g., 2000s vs. 2010s vs. 2020s) to capture long-term trajectory."
    },
    {
      "name": "Reporting Coverage Rate",
      "description": "The proportion of countries with available homicide data in any given year, reflecting data completeness and global monitoring capacity."
    }
  ],
  "analysis_dimensions": [
    "country",
    "year",
    "sex",
    "age_group",
    "homicide_rate"
  ]
}

